insert into public.pages (slug, title, seo_title, seo_description, noindex) values
  ('next/lab', 'The Lab', 'The Lab · European market entry for independent brands', 'Test your brand’s readiness for a new European market, compare markets on sourced information and find compatible retail and distribution partners. By Not by Accident, Amsterdam.', false),
  ('next/lab-how', 'The Lab · How it works', 'How The Lab works · Readiness scoring and partner matching', 'The methodology behind The Lab: how expansion readiness is scored, how markets are compared and how partner matches are calculated and explained.', false),
  ('next/lab-readiness', 'The Lab · Readiness preview', 'Expansion readiness test for consumer brands · The Lab', 'Six questions, two minutes: an indicative read on how ready your brand is for a new European market. Free, and nothing you answer is stored.', false),
  ('next/lab-app', 'The Lab · App microcopy', 'The Lab', 'Your Lab workspace.', true)
on conflict (slug) do nothing;

