insert into public.page_sections (page_id, section_key, eyebrow, title, subtitle, body, cta_label, cta_url, image_media_id, video_url, sort_order, extra)
select id, 'problem', 'The problem', 'Expansion advice arrives in pieces.', null, 'One firm sells you a market report. Another sells a database. A consultant explains the report, an agency does the outreach, and nobody joins the pieces up. The decision lands back on your desk with four invoices attached.', null, null, null, null, 1, '{}'::jsonb
from public.pages where slug = 'next/lab'
