insert into public.page_sections (page_id, section_key, eyebrow, title, subtitle, body, cta_label, cta_url, image_media_id, video_url, sort_order, extra)
select id, 'capabilities', 'What it does', 'Four steps, one place.', null, null, null, null, null, null, 2, '{"items":[{"title":"Validate","meta":"01","body":"About twenty questions across six areas, from positioning to returns. A readiness score you can trace back, answer by answer."},{"title":"Understand","meta":"02","body":"Up to three markets side by side. Where we hold verified information we show the source and the date it was checked. Where we don’t, we say so."},{"title":"Match","meta":"03","body":"Partners scored on category, geography, price, customer, distribution and readiness, with the reasons written out and the gaps flagged."},{"title":"Act","meta":"04","body":"Request introductions, follow their progress, and keep the conversations that matter in one short pipeline."}]}'::jsonb
from public.pages where slug = 'next/lab'
on conflict (page_id, section_key) do nothing;
