insert into public.page_sections (page_id, section_key, eyebrow, title, subtitle, body, cta_label, cta_url, image_media_id, video_url, sort_order, extra)
select id, 'faq', 'Questions', 'Before you sign up.', null, null, null, null, null, null, 7, '{"items":[{"title":"Is the readiness score a prediction?","body":"No. It summarises your own answers against a published method. A band such as “Pilot-ready potential” describes how prepared you are, not how likely you are to succeed."},{"title":"Where does the market information come from?","body":"From profiles our team maintains, each with its sources and the date it was last checked. A profile that holds basic facts only is labelled that way."},{"title":"Are the partners expecting my introduction?","body":"Not necessarily. Every partner carries a status, from research prospect to confirmed participating partner, and our team reviews each request before anyone is contacted."},{"title":"Who sees my data?","body":"You, anyone you add to your brand, and our team when running introductions. Nothing goes to a partner unless you ask for an introduction. You can export or delete everything from Settings."},{"title":"Which markets are covered?","body":"We start with the Netherlands, Germany, the United Kingdom, France, Belgium, Denmark, Sweden, Italy and Spain, and add others as we research them."}]}'::jsonb
from public.pages where slug = 'next/lab'
on conflict (page_id, section_key) do nothing;
