insert into public.page_sections (page_id, section_key, eyebrow, title, subtitle, body, cta_label, cta_url, image_media_id, video_url, sort_order, extra)
select id, 'readiness', null, 'Readiness', null, 'Each question belongs to one of six areas and carries a weight. An answer earns 0 to 100 points. An area’s score is the weighted average of the questions that apply to you; questions that don’t apply, such as returns for a software company, leave the calculation instead of counting as zero. The overall score combines the areas with the weights below. Every result records the version of the questions and weights it used, so an old report never changes when the method does.', null, null, null, null, 1, '{}'::jsonb
from public.pages where slug = 'next/lab-how'
on conflict (page_id, section_key) do nothing;
