insert into public.page_sections (page_id, section_key, eyebrow, title, subtitle, body, cta_label, cta_url, image_media_id, video_url, sort_order, extra)
select id, 'market', null, 'Market fit', null, 'For each market we combine your overall readiness, any existing presence, language readiness, logistics capability (with a rule for crossing the EU customs border) and the partners in our database for your category. A market-fit score appears only when there is enough to go on, and markets are ranked only when the scores are at least five points apart. Every factor is labelled by where its evidence comes from: your answers, our verified profiles, our partner records or a product rule.', null, null, null, null, 3, '{}'::jsonb
from public.pages where slug = 'next/lab-how'
on conflict (page_id, section_key) do nothing;
insert into public.page_sections (page_id, section_key, eyebrow, title, subtitle, body, cta_label, cta_url, image_media_id, video_url, sort_order, extra)
